package com.boostperformance;

import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

import java.awt.*;

@ConfigGroup("boostperformance")
public interface BoostPerformanceConfig extends Config
{
    @ConfigSection(name="General", description="General settings", position=1, closedByDefault=false)
    String generalSection = "general";

    @ConfigSection(name="Respawn", description="Respawn settings", position=2, closedByDefault=true)
    String respawnSection = "respawn";

    @ConfigSection(name="Infobox", description="Infobox settings", position=3, closedByDefault=true)
    String infoboxSection = "infobox";

    @ConfigItem(
            keyName = "isMain",
            name = "Is Main",
            description = "You should be getting the drops (multiple may be the main, only necessary if main in party)",
            position = 1,
            section = generalSection
    )
    default boolean isMain()
    {
        return false;
    }

    @ConfigItem(
            position = 2,
            keyName = "displayKillMessage",
            name = "Display Kill Message",
            description = "Display game message with information about the kill upon boss death.",
            section = generalSection
    )
    default boolean getDisplayKillMessage()
    {
        return false;
    }

    @ConfigItem(
            position = 3,
            keyName = "displayKillMessage",
            name = "Display Reset Message",
            description = "Display game message when a reset has occured.",
            section = generalSection
    )
    default boolean getDisplayResetMessage()
    {
        return true;
    }

    @ConfigItem(
            keyName = "preventFalloff",
            name = "Prevent Falloff",
            description = "Current & overall duration only update on kill for more accuracy.",
            position = 4,
            section = generalSection
    )
    default boolean getPreventFallOff()
    {
        return true;
    }

    @ConfigItem(
            keyName = "displayRespawns",
            name = "Display Respawns",
            description = "Displays respawns of given bosses without the memory leak issue/inconsistency of dyanmic respawn timers.",
            position = 5,
            section = respawnSection
    )
    default boolean displayStaticRespawns()
    {
        return false;
    }

    @Alpha
    @ConfigItem(
            keyName = "tileColor",
            name = "Tile Color",
            description = "Respawn tile color",
            position = 6,
            section = respawnSection
    )
    default Color respawnTileColor()
    {
        return new Color(255,255,255,122);
    }

    @Alpha
    @ConfigItem(
            keyName = "staleWorldColor",
            name = "Stale World Color",
            description = "Respawn color when most recent kill was not in this world",
            position = 7,
            section = respawnSection
    )
    default Color staleWorldColor()
    {
        return new Color(255,0,0,255);
    }

    @Range(min=0,max = 16)
    @ConfigItem(
            keyName = "tileWidth",
            name = "Tile Width",
            description = "Width of tile outline",
            position = 8,
            section = respawnSection
    )
    default int respawnTileWidth()
    {
        return 2;
    }

    @Alpha
    @ConfigItem(
            keyName = "textColor",
            name = "Text Color",
            description = "Respawn ticks text color",
            position = 9,
            section = respawnSection
    )
    default Color respawnTextColor()
    {
        return Color.orange;
    }

    @Range(min=6,max=40)
    @ConfigItem(
            keyName = "textSize",
            name = "Text Size",
            description = "Respawn ticks text size",
            position = 10,
            section = respawnSection
    )
    default int respawnTextSize()
    {
        return 22;
    }

    @ConfigItem(
            keyName = "showInfobox",
            name = "Show Infobox",
            description = "Show infbox representing kills from the panel",
            position = 10,
            section = infoboxSection
    )
    default boolean showInfobox()
    {
        return false;
    }

    @ConfigItem(
            keyName = "infoboxDisplay",
            name = "Infobox Display",
            description = "Which section from the panel to display",
            position = 11,
            section = infoboxSection
    )
    default BoostPerformancePlugin.PERFORMANCE_SECTION infoDisplay()
    {
        return BoostPerformancePlugin.PERFORMANCE_SECTION.CURRENT;
    }

    @ConfigItem(
            keyName = "hideBeforeKC",
            name = "Hide Before KC",
            description = "Only displays the infobox after this many kills.",
            position = 12,
            section = infoboxSection
    )
    default int hideBeforeKC()
    {
        return 100;
    }

    @ConfigItem(
            keyName = "alwaysShowKC",
            name = "Always Show KC",
            description = "Ignores previous two settings, permanently shows kc (like staring at a clock but you do you)",
            position = 13,
            section = infoboxSection
    )
    default boolean alwaysShowKC()
    {
        return true;
    }

    @ConfigItem(
            keyName = "includeSnipes",
            name = "Include Snipes",
            description = "Include snipes as part of the kc shown (true kc)",
            position = 14,
            section = infoboxSection
    )
    default boolean includeSnipes()
    {
        return false;
    }

}

package com.boostperformance;

import net.runelite.client.ui.PluginPanel;
import net.runelite.client.util.ImageUtil;
import net.runelite.client.util.SwingUtil;

import javax.swing.*;
import javax.swing.border.BevelBorder;
import java.awt.*;

import static com.boostperformance.BoostPerformancePlugin.PERFORMANCE_SECTION;
public class BoostPerformancePanel extends PluginPanel
{
    BoostPerformancePlugin plugin;

    Utils utils;

    private JPanel panelBossHeader,panelCurrentHeader,panelOverallHeader;
    private RoundedPanel  panelCurrentInfo, panelOverallInfo;
    private InfoLabel labelCurrentInfoKPH, labelCurrentInfoKC, labelCurrentInfoSnipes, labelCurrentInfoEHB, labelCurrentInfoPB,labelCurrentInfoDuration,
            labelOverallInfoKPH, labelOverallInfoKC, labelOverallInfoSnipes, labelOverallInfoEHB, labelOverallInfoPB,labelOverallInfoDuration;
    private HeaderLabel labelBossHeader,labelCurrentHeaderTitle, labelOverallHeaderTitle;
    private JButton buttonCurrentReset, buttonCurrentPause, buttonOverallReset;
    private final Color SUB_PANEL_COLOR_MAIN = new Color(30, 30, 30);
    private final Color SUB_PANEL_COLOR_HEADER = new Color(30, 30, 30);

    private final ImageIcon resetImage = new ImageIcon(ImageUtil.loadImageResource(getClass(), "icon_Reset.png"));
    private final ImageIcon pauseImage = new ImageIcon(ImageUtil.loadImageResource(getClass(), "icon_Pause.png"));
    private final ImageIcon clockImage = new ImageIcon(ImageUtil.loadImageResource(getClass(), "icon_Clock.png"));
    private final static String baseKPHString = "KPH: ";
    private final static String baseKCString = "KC: ";
    private final static String baseSnipeString = "Snipes: ";
    private final static String baseEHBString = "EHB: ";
    private final static  String basePBString = "PB: ";

    BoostPerformancePanel(BoostPerformancePlugin plugin) {
        super();
        this.plugin = plugin;
        this.utils = plugin.utils;
        InitComponents();

        /*Boss Section Start*/
        SetUpHeaderPanel(panelBossHeader,labelBossHeader,"Kill a boss...",45,true);

        /*Current Section Start*/
        SetUpHeaderPanel(panelCurrentHeader,labelCurrentHeaderTitle,"Current",40,false);
        SetUpInfoPanel(panelCurrentInfo,labelCurrentInfoKPH,labelCurrentInfoKC,labelCurrentInfoSnipes,labelCurrentInfoEHB,labelCurrentInfoPB,labelCurrentInfoDuration,buttonCurrentReset,buttonCurrentPause);

        /*Overall Section Start*/
        SetUpHeaderPanel(panelOverallHeader,labelOverallHeaderTitle,"Overall",40,false);
        SetUpInfoPanel(panelOverallInfo,labelOverallInfoKPH,labelOverallInfoKC,labelOverallInfoSnipes,labelOverallInfoEHB,labelOverallInfoPB,labelOverallInfoDuration,buttonOverallReset,null);

        /*Add all to screen*/
        GroupLayout layout = new GroupLayout(this);
        this.setLayout(layout);
        layout.setHorizontalGroup(layout.createSequentialGroup()
                                .addContainerGap()
                                .addGroup(layout.createParallelGroup()
                                        .addComponent(panelOverallInfo)
                                        .addComponent(panelOverallHeader)
                                        .addComponent(panelBossHeader)
                                        .addComponent(panelCurrentInfo)
                                        .addComponent(panelCurrentHeader))
                                .addContainerGap()

        );
        layout.setVerticalGroup(
                layout.createSequentialGroup()
                        .addContainerGap()
                        .addComponent(panelBossHeader)
                        .addPreferredGap(LayoutStyle.ComponentPlacement.RELATED, GroupLayout.DEFAULT_SIZE, Short.MAX_VALUE)
                        .addComponent(panelCurrentHeader)
                        .addComponent(panelCurrentInfo, GroupLayout.PREFERRED_SIZE, GroupLayout.DEFAULT_SIZE, GroupLayout.PREFERRED_SIZE)
                        .addPreferredGap(LayoutStyle.ComponentPlacement.RELATED)
                        .addComponent(panelOverallHeader)
                        .addComponent(panelOverallInfo, GroupLayout.PREFERRED_SIZE, GroupLayout.DEFAULT_SIZE, GroupLayout.PREFERRED_SIZE)
                        .addContainerGap()
        );
    }

    /**
     * Initiate Components
     *
     */
    void InitComponents(){

        panelBossHeader = new JPanel();
        labelBossHeader = new HeaderLabel();
        panelCurrentHeader = new JPanel();
        labelCurrentHeaderTitle = new HeaderLabel();
        panelCurrentInfo = new RoundedPanel(16);
        labelCurrentInfoKPH = new InfoLabel();
        labelCurrentInfoKC = new InfoLabel();
        labelCurrentInfoSnipes = new InfoLabel();
        labelCurrentInfoEHB = new InfoLabel();
        labelCurrentInfoPB = new InfoLabel();
        labelCurrentInfoDuration = new InfoLabel();
        buttonCurrentReset = new JButton(resetImage);
        buttonCurrentPause = new JButton(pauseImage);
        panelOverallHeader = new JPanel();
        labelOverallHeaderTitle = new HeaderLabel();
        panelOverallInfo = new RoundedPanel(16);
        labelOverallInfoKPH = new InfoLabel();
        labelOverallInfoKC = new InfoLabel();
        labelOverallInfoSnipes = new InfoLabel();
        labelOverallInfoEHB = new InfoLabel();
        labelOverallInfoPB = new InfoLabel();
        labelOverallInfoDuration = new InfoLabel();
        buttonOverallReset = new JButton(resetImage);

        buttonCurrentReset.setFocusPainted(false);
        buttonCurrentReset.addActionListener(e ->
                plugin.ResetCurrent());
        buttonCurrentPause.setFocusPainted(false);
        buttonCurrentPause.addActionListener(e ->
                plugin.PauseCurrent());

        buttonOverallReset.setFocusPainted(false);
        buttonOverallReset.addActionListener(e ->
                plugin.ResetOverall());

    }

    /**
     * Initial setup of Header panel
     * Sets color,label data and grid layout settings
     *
     */
    private void SetUpHeaderPanel(JPanel headerPanel, HeaderLabel titleLabel, String header, int headerSizeV, boolean hasBorder){
        titleLabel.setText(header);
        if(hasBorder)
        {
            headerPanel.setBackground(SUB_PANEL_COLOR_HEADER);
            titleLabel.setBorder(BorderFactory.createBevelBorder(BevelBorder.RAISED));
        }

        GroupLayout layout = new GroupLayout(headerPanel);
        headerPanel.setLayout(layout);
        layout.setHorizontalGroup(
                layout.createParallelGroup(GroupLayout.Alignment.LEADING)
                        .addGroup(layout.createSequentialGroup()
                                .addComponent(titleLabel, GroupLayout.DEFAULT_SIZE, GroupLayout.DEFAULT_SIZE, Short.MAX_VALUE)
                        )
        );
        layout.setVerticalGroup(
                layout.createParallelGroup(GroupLayout.Alignment.LEADING)
                        .addGroup(layout.createSequentialGroup()
                                .addComponent(titleLabel, GroupLayout.DEFAULT_SIZE, headerSizeV, Short.MAX_VALUE)
                        )
        );
    }
    /**
     * Initial setup of Info panel
     * Sets color,dimension,label defaults and grid layout settings
     *
     */
    private void SetUpInfoPanel(RoundedPanel infoPanel, InfoLabel kph, InfoLabel kc,
                                InfoLabel snipes, InfoLabel ehb, InfoLabel pb,
                                InfoLabel duration, JButton resetButton, JButton pauseButton) {

        infoPanel.setBackground(SUB_PANEL_COLOR_MAIN);
        infoPanel.setLayout(new BoxLayout(infoPanel, BoxLayout.Y_AXIS));
        infoPanel.setBorder(BorderFactory.createEmptyBorder(10, 12, 2, 12));

        kph.setInfo(baseKPHString,"--");
        kc.setInfo(baseKCString,"0");

        snipes.setInfo(baseSnipeString,"0");

        ehb.setInfo(baseEHBString,"--");
        pb.setInfo(basePBString,"--");

        duration.setInfoNoLabel("0:00:00");

        addInfoRow(infoPanel,kph);
        addInfoRow(infoPanel,kc);
        addInfoRow(infoPanel,snipes);
        addInfoRow(infoPanel,ehb);
        addInfoRow(infoPanel,pb);


        //Bottom info bar
        JPanel row = new JPanel();
        row.setOpaque(false);
        row.setLayout(new BoxLayout(row, BoxLayout.X_AXIS));
        row.setAlignmentX(Component.LEFT_ALIGNMENT);

        JLabel icon = new JLabel(clockImage);
        icon.setAlignmentY(Component.CENTER_ALIGNMENT);
        duration.setAlignmentY(Component.CENTER_ALIGNMENT);

        row.add(icon);
        row.add(Box.createHorizontalStrut(6));
        row.add(duration);
        row.add(Box.createHorizontalGlue());

        if(pauseButton != null){
            SwingUtil.removeButtonDecorations(pauseButton);
            row.add(pauseButton);
        }

        SwingUtil.removeButtonDecorations(resetButton);
        row.add(resetButton);

        infoPanel.add(row);

    }

    public void addInfoRow(JPanel panel, JComponent label){
        JPanel row = new JPanel();
        row.setOpaque(false);
        row.setLayout(new BoxLayout(row, BoxLayout.X_AXIS));
        row.setAlignmentX(Component.LEFT_ALIGNMENT);
        row.add(label);

        panel.add(row);
        panel.add(Box.createVerticalStrut(4));
        panel.add(new JSeparator());
        panel.add(Box.createVerticalStrut(4));
    }

    /**
     * Set KPH Text of given section
     */
    public void SetKPH(PERFORMANCE_SECTION section){
        String kphText = utils.GetKillsPerHourString(section,true);
        boolean current = section == PERFORMANCE_SECTION.CURRENT;
        if(current){
            labelCurrentInfoKPH.setValue(kphText);
        }else{
            labelOverallInfoKPH.setValue(kphText);
        }
    }
    /**
     * Set KC Text of given section
     */
    public void SetKC(PERFORMANCE_SECTION section){
        String kcText = utils.GetKCString(section);
        boolean current = section == PERFORMANCE_SECTION.CURRENT;
        if(current){
            labelCurrentInfoKC.setValue(kcText);
        }else{
            labelOverallInfoKC.setValue(kcText);
        }
    }
    /**
     * Set Snipe Text of given section
     */
    public void SetSnipes(PERFORMANCE_SECTION section){
        String snipeText = utils.GetSnipeString(section);
        boolean current = section == PERFORMANCE_SECTION.CURRENT;
        if(current){
            labelCurrentInfoSnipes.setValue(snipeText);
        }else{
            labelOverallInfoSnipes.setValue(snipeText);
        }
    }
    /**
     * Set EHB Text of given section
     */
    public void SetEHB(PERFORMANCE_SECTION section){
        String ehbText = utils.GetEHBString(section);
        boolean current = section == PERFORMANCE_SECTION.CURRENT;
        if(current){
            labelCurrentInfoEHB.setValue(ehbText);
        }else{
            labelOverallInfoEHB.setValue(ehbText);
        }
    }
    /**
     * Set Duration Text of given section
     */
    public void SetDuration(PERFORMANCE_SECTION section, boolean preventFall){
        String durationText = utils.GetDurationString(section,preventFall);
        boolean current = section == PERFORMANCE_SECTION.CURRENT;
        if(current){
            labelCurrentInfoDuration.setText(durationText);
        }else{
            labelOverallInfoDuration.setText(durationText);
        }
    }
    /**
     * Set PB Text of given section
     */
    public void SetPB(PERFORMANCE_SECTION section){
        String pbText = utils.GetPBString(section);
        boolean current = section == PERFORMANCE_SECTION.CURRENT;
        if(current){
            labelCurrentInfoPB.setValue(pbText);
        }else{
            labelOverallInfoPB.setValue(pbText);
        }
    }

    /**
     * Set Boss header to the recent boss name
     * For dks and other potential partner bosses, we generate a name based on the current partners short-names
     * EX dks multi: Dagannoth Rex and Dagannoth Prime would be "Rex,Prime"
     * EX dks single: Dagannoth Rex would be "Dagannoth Rex"
     */
    public void SetBossName(){
        if(plugin.currentPartnerBosses != null){
            labelBossHeader.setText(BossData.GetBossName(plugin.currentPartnerBosses));
        }else
        {
            labelBossHeader.setText(plugin.recentKillName);
        }
    }

    /**
     * Sets Overall section to be invalid/mixed
     * Differing bosses that aren't partners(dks) are tracked in overall
     * To prevent confusion/fake inflated values, indicate to the user that overall tracking has multiple different sessions
     */
    public void SetInvalidOverall(boolean invalid){
        labelOverallHeaderTitle.setText(invalid ? "Mixed Overall" : "Overall");
    }


}

package com.boostperformance;

import com.boostperformance.messages.BoostPerformanceMemberUpdate;
import com.boostperformance.messages.BoostPerformanceDespawnUpdate;
import com.boostperformance.messages.BoostPerformanceSnipeUpdate;
import com.boostperformance.messages.BoostPerformanceSpawnUpdate;
import com.google.gson.Gson;
import com.google.inject.Provides;
import com.google.common.collect.BiMap;
import com.google.common.collect.HashBiMap;
import javax.inject.Inject;
import javax.swing.*;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.*;
import net.runelite.client.chat.ChatColorType;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.PartyChanged;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.party.PartyService;
import net.runelite.client.party.WSClient;
import net.runelite.client.party.events.UserJoin;
import net.runelite.client.party.events.UserPart;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.ui.overlay.infobox.InfoBoxManager;
import net.runelite.client.util.ExecutorServiceExceptionLogger;
import net.runelite.client.util.ImageUtil;
import net.runelite.client.util.Text;

import java.awt.*;
import java.awt.image.BufferedImage;
import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.net.URL;
import java.time.Duration;
import java.time.Instant;
import java.util.Arrays;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Optional;
import java.util.Set;
import java.util.concurrent.*;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

@Slf4j
@PluginDescriptor(
	name = "Boost Performance",
	description = "Track performance of a boost session or clan event as a participant or bystander"
)
public class BoostPerformancePlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private BoostPerformanceConfig config;

	@Inject
	private ChatMessageManager chatMessageManager;

	@Inject
	private PartyService partyService;

	@Inject
	private WSClient wsClient;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private Gson gson;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private RespawnOverlay overlay;

	@Inject
	private InfoBoxManager infoBoxManager;

	@Inject
	private ItemManager itemManager;

	final Color BAD_HIGHLIGHT = new Color(90,90,90);
	final Color GOOD_HIGHLIGHT = new Color(239,16,32);

	final int SECONDS_FOR_GOOD_ESTIMATE = 1200;
	private final String DYNAMIC_BOSS_DATA_URL = "https://1defence.github.io/resources/data.json";

	private final String ADDITIONAL_BOSS_DATA_URL = "https://1defence.github.io/resources/additionalData.json";
	String KC_REGEX = "^Your (.+?) kill count is";
	Pattern KC_REGEX_PATTERN = Pattern.compile(KC_REGEX);

	private ExecutorService bossDataExecutorService;

	BiMap<Long, String> partyMembers = HashBiMap.create();
	public HashMap<Integer, Set<Integer>> worldsActive = new HashMap<>();

	public HashMap<Integer, Set<RespawnData>> respawnsActive = new HashMap<>();

	Instant killStartTime,
			currentStartTime = null;

	String recentKillName;

	long currentFastestKill = -1;
	int currentBossKills,currentSnipes = 0;
	int worldOfPreviousKill,worldOfRecentKill,recentKillId = -1;
	Set<Integer> currentPartnerBosses = null;
	BoostPerformancePanel boostPerformancePanel;
	private NavigationButton navButton;

	public enum PERFORMANCE_SECTION {CURRENT,OVERALL}

	public Utils utils;

	private boolean queuedUpdate = false;
	private String currentLocalUsername;

	boolean paused = false;

	Duration totalPausedDuration = Duration.ZERO;//needs a rename, its the total paused of current, not to be confused with overall total
	int pausedKCs = 0;

	boolean configShowKCInfobox,configAlwaysShow,configIncludeSnipe;
	int configHideBeforeKC;

	PERFORMANCE_SECTION configInfoDisplay;

	@Provides
	BoostPerformanceConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(BoostPerformanceConfig.class);
	}

	@Override
	protected void startUp() throws Exception
	{
		currentStartTime = null;
		currentPartnerBosses = null;
		currentBossKills = currentSnipes = 0;
		currentFastestKill = recentKillId = -1;
		worldOfRecentKill = -1;
		worldOfPreviousKill = -1;
		queuedUpdate = true;
		paused = false;
		totalPausedDuration = Duration.ZERO;
		pausedKCs = 0;
		PerformanceStats.Clear(this);
		utils = new Utils(this);

		overlayManager.add(overlay);
		overlay.CacheConfigs();
		CacheConfigs();

		wsClient.registerMessage(BoostPerformanceSpawnUpdate.class);
		wsClient.registerMessage(BoostPerformanceDespawnUpdate.class);
		wsClient.registerMessage(BoostPerformanceSnipeUpdate.class);
		wsClient.registerMessage(BoostPerformanceMemberUpdate.class);

		bossDataExecutorService = new ExecutorServiceExceptionLogger(Executors.newSingleThreadScheduledExecutor());
		bossDataExecutorService.execute(this::FetchBossData);

		//request a sync from party members, dont inform join, the queuedUpdate will do this.
		SendMemberUpdate(false,false,true,null);
	}

	@Override
	protected void shutDown() throws Exception
	{
		//inform party members to remove us, in future add a heart-beat check to handle X-ing out on the client
		SendMemberUpdate(false,true,false,null);

		wsClient.unregisterMessage(BoostPerformanceSpawnUpdate.class);
		wsClient.unregisterMessage(BoostPerformanceDespawnUpdate.class);
		wsClient.unregisterMessage(BoostPerformanceSnipeUpdate.class);
		wsClient.unregisterMessage(BoostPerformanceMemberUpdate.class);

		overlayManager.remove(overlay);

		clientToolbar.removeNavigation(navButton);

		bossDataExecutorService.shutdown();
		bossDataExecutorService = null;
	}

	void CacheConfigs(){
		configShowKCInfobox = config.showInfobox();
		configAlwaysShow = config.alwaysShowKC();
		configIncludeSnipe = config.includeSnipes();
		configHideBeforeKC = config.hideBeforeKC();
		configInfoDisplay = config.infoDisplay();
	}

	void CreateInfoBox(){
		if(!configShowKCInfobox)
			return;

		if (GetInfoBox().isEmpty())
		{
			KillcountInfoBox kcInfobox = new KillcountInfoBox(itemManager.getImage(ItemID.DAGANNOTH_BONES), this);
			infoBoxManager.addInfoBox(kcInfobox);
		}
	}

	void RemoveInfoBox(){
		Optional<KillcountInfoBox> kcInfoboxOpt = GetInfoBox();

		if (kcInfoboxOpt.isPresent())
		{
			KillcountInfoBox kcInfobox = kcInfoboxOpt.get();
			infoBoxManager.removeInfoBox(kcInfobox);
		}

	}

	Optional<KillcountInfoBox> GetInfoBox(){
		return infoBoxManager.getInfoBoxes().stream()
				.filter(KillcountInfoBox.class::isInstance)
				.map(KillcountInfoBox.class::cast)
				.findAny();
	}


	/**
	 * Grab up to date EHB rates from github IO page
	 * allows data to stay up to date without redundant update PRs
	 * will in future include all boss data to allow new bosses to be added seemlessly
	 */
	private void FetchBossData(){
		SwingUtilities.invokeLater(() ->
		{
			BufferedReader reader;
			try
			{
				reader = new BufferedReader(new InputStreamReader(new URL(ADDITIONAL_BOSS_DATA_URL).openStream()));
				AdditionalBossDataJson[] fetchedAdditionalData = gson.fromJson(reader, AdditionalBossDataJson[].class);
				for (AdditionalBossDataJson data : fetchedAdditionalData)
				{
					BossData.AddBoss(
							data.getSpawnFormId(),
							data.getFinalFormId(),
							data.getValidPartners(),
							data.getShortName(),
							data.getFullName(),
							data.getSpawnSeconds(),
							data.getDeathAnimationId(),
							data.getEhb(),
							data.getSpawnLocation(),
							data.getSize());
				}
				reader.close();

				reader = new BufferedReader(new InputStreamReader(new URL(DYNAMIC_BOSS_DATA_URL).openStream()));
				DynamicBossDataJson[] fetchedDynamicData = gson.fromJson(reader, DynamicBossDataJson[].class);
				for (DynamicBossDataJson data : fetchedDynamicData)
				{
					BossData.SetBossEHB(data.getBossSpawnFormId(),data.getEhb());
				}
				reader.close();

				//data gathered, can initiate panel.
				InitiatePanel();

			} catch (IOException e)
			{
				throw new RuntimeException(e);
			}
		});


	}

